#include <bits/stdc++.h>
using namespace std;

int pos(const std::vector<char>& s, int a, int b, int c, int k) {
    int ret = 0;
    for (char x : s) {
        if (x == 'V') {
            if (a == 0) {
                if (k == 0) return ret;
                ret++;
            } else {
                a--;
            }
        } else if (x == 'K') {
            if (b == 0) {
                if (k == 1) return ret;
                ret++;
            } else {
                b--;
            }
        } else {
            if (c == 0) {
                if (k == 2) return ret;
                ret++;
            } else {
                c--;
            }
        }
    }
    return -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    std::string lineS;
    cin >> lineS;
    std::vector<char> s(lineS.begin(), lineS.end());

    int vCount = 0, kCount = 0, eCount = 0;
    for (char c : s) {
        if (c == 'V') vCount++;
        else if (c == 'K') kCount++;
        else eCount++;
    }

    const int INF = INT_MAX;
    int dp[3][vCount + 1][kCount + 1][eCount + 1];
    for (int l = 0; l < 3; ++l)
        for (int i = 0; i <= vCount; ++i)
            for (int j = 0; j <= kCount; ++j)
                for (int k = 0; k <= eCount; ++k)
                    dp[l][i][j][k] = INF;

    dp[2][0][0][0] = 0;

    int poss[3][vCount + 1][kCount + 1][eCount + 1];
    for (int i = 0; i <= vCount; ++i)
        for (int j = 0; j <= kCount; ++j)
            for (int k = 0; k <= eCount; ++k)
                for (int l = 0; l < 3; ++l)
                    poss[l][i][j][k] = pos(s, i, j, k, l);

    for (int i = 0; i <= vCount; ++i) {
        for (int j = 0; j <= kCount; ++j) {
            for (int k = 0; k <= eCount; ++k) {
                if (i + 1 <= vCount && poss[0][i][j][k] != -1) {
                    int v = poss[0][i][j][k];
                    if (dp[2][i][j][k] != INF)
                        dp[0][i + 1][j][k] = std::min(dp[0][i + 1][j][k], dp[2][i][j][k] + v);
                    if (dp[1][i][j][k] != INF)
                        dp[0][i + 1][j][k] = std::min(dp[0][i + 1][j][k], dp[1][i][j][k] + v);
                    if (dp[0][i][j][k] != INF)
                        dp[0][i + 1][j][k] = std::min(dp[0][i + 1][j][k], dp[0][i][j][k] + v);
                }
                if (j + 1 <= kCount && poss[1][i][j][k] != -1) {
                    int v = poss[1][i][j][k];
                    if (dp[2][i][j][k] != INF)
                        dp[1][i][j + 1][k] = std::min(dp[1][i][j + 1][k], dp[2][i][j][k] + v);
                    if (dp[1][i][j][k] != INF)
                        dp[1][i][j + 1][k] = std::min(dp[1][i][j + 1][k], dp[1][i][j][k] + v);
                }
                if (k + 1 <= eCount && poss[2][i][j][k] != -1) {
                    int v = poss[2][i][j][k];
                    if (dp[2][i][j][k] != INF)
                        dp[2][i][j][k + 1] = std::min(dp[2][i][j][k + 1], dp[2][i][j][k] + v);
                    if (dp[1][i][j][k] != INF)
                        dp[2][i][j][k + 1] = std::min(dp[2][i][j][k + 1], dp[1][i][j][k] + v);
                    if (dp[0][i][j][k] != INF)
                        dp[2][i][j][k + 1] = std::min(dp[2][i][j][k + 1], dp[0][i][j][k] + v);
                }
            }
        }
    }

    int answer = std::min({dp[0][vCount][kCount][eCount], dp[1][vCount][kCount][eCount], dp[2][vCount][kCount][eCount]});
    std::cout << answer << "\n";

    return 0;
}

